	font-weight: bold;
	padding:5px 7px 5px 7px;
}

._neutral {
	background: rgba(15,15,15,0.95);
border: 1px solid #232323;
text-shadow: 0px 1px 1px #171717;
  	color: #ccc;
}

._minus {
  	background: rgba(15,15,15,0.95);
border: 1px solid #232323;
text-shadow: 0px 1px 1px #171717;
  	color: #ccc;
}

._plus {
	background: rgba(15,15,15,0.95);
border: 1px solid #232323;
text-shadow: 0px 1px 1px #171717;
  	color: #ccc;
}

img {
	border: none;
}

img.attachment {
		background: rgba(15,15,15,0.95);
border: 1px solid #232323;
text-shadow: 0px 1px 1px #171717;
  	color: #ccc;
	padding: 2px;
}

hr {
	background-color: #000;
	color: #ccc;
	height: 1px;
	border: 0px;
}

.clear {
	clear: both;
}

.float_left {
	float: left;
}

.float_right {
	float: right;
}

.hidden {
	display: none;
	float: none;
	width: 1%;
}

.hiddenrow {
	display: none;
}

.selectall {
		background: rgba(15,15,15,0.95);
border-bottom: 1px solid #232323;
text-shadow: 0px 1px 1px #171717;
  	color: #ccc;
	text-align: center;
}

.expcolimage {
	float: right;
	width: auto;
	vertical-align: middle;
	margin-top: 3px;
}

.tcat_menu > .expcolimage {
	margin-top: 0;
}

blockquote {
	background: #232323;
	color: #a1a1a1;
	text-shadow: 0px 1px 1px #181818;
	border-left: 6px solid #3f9889;
	margin: 0;
	padding: 20px;
	-moz-border-top-left-radius: 3px;
	-webkit-border-top-left-radius: 3px;
	border-top-left-radius: 3px;
	font: normal 13px tahoma,helvetica,arial,sans-serif;
	
	font-style: normal;
}

blockquote cite {
	text-shadow: 0px 1px 1px #181818;
	display: block;
	margin: -15px -15px 5px -15px;
	padding: 10px;
	-moz-border-top-left-radius: 3px;
	-webkit-border-top-left-radius: 3px;
	border-top-left-radius: 3px;
	-moz-border-top-right-radius: 3px;
	-webkit-border-top-right-radius: 3px;
	border-top-right-radius: 3px;
	border-bottom: 1px dashed #383838;
	
	color: #a1a1a1;
    font: normal 13px tahoma,helvetica,arial,sans-serif;
	font-style: normal;
	font-weight: bold;
	text-decoration: none;
}

blockquote cite span {
	color: #a1a1a1;
	float: right;
	text-shadow: 0px 1px 1px #181818;
    font: normal 13px tahoma,helvetica,arial,sans-serif;
	font-style: normal;
}

blockquote cite span.highlight {
	float: none;
	font-weight: bold;
	padding-bottom: 0;
}

.codeblock {
	background: #232323;
	color: #a1a1a1;
	text-shadow: 0px 1px 1px #181818;
	border-left: 6px solid #b4b3b3;
	-moz-border-top-left-radius: 3px;
	-webkit-border-top-left-radius: 3px;
	border-top-left-radius: 3px;
	padding: 20px;
	font: normal 13px tahoma,helvetica,arial,sans-serif;
	-moz-border-top-left-radius: 3px;
	-webkit-border-top-left-radius: 3px;
	border-top-left-radius: 3px;
	
	font-style: normal;
}

.codeblock .title {
	color: #a1a1a1;
	border-bottom: 1px dashed #383838;
	text-shadow: 1px 1px 0px #181818;
	-moz-background-clip: padding;
	-webkit-background-clip: padding-box;
	font-weight: bold;
	margin: -15px -15px 5px -15px;
	padding: 10px;
	-moz-border-top-left-radius: 3px;
	-webkit-border-top-left-radius: 3px;
	border-top-left-radius: 3px;
	padding-bottom: 3px;
	-moz-border-top-right-radius: 3px;
	-webkit-border-top-right-radius: 3px;
	border-top-right-radius: 3px;
    font: normal 13px tahoma,helvetica,arial,sans-serif;
	font-style: normal;
}

.codeblock code {
	overflow: auto;
	height: auto;
	max-height: 200px;
	display: block;
    font: normal 13px tahoma,helvetica,arial,sans-serif;
	font-style: normal;
}

.smilie {
	vertical-align: middle;
}

.smilie_pointer {
	cursor: pointer;
}

.separator {
	margin: 5px;
	padding: 0;
	height: 0px;
	font-size: 1px;
	list-style-type: none;
}

.popup_menu .popup_item_container {
	margin: 1px;
	text-align: left;
}

.popup_menu .popup_item {
	display: block;
	padding: 6px;
	white-space: nowrap;
	
	text-decoration: none;
}

.popup_menu a.popup_item:hover {
	background: #3f9889;
	color: #fff;
	text-shadow: rgba(0,0,0,0.25) 0px 1px 1px;
	-webkit-transition: all 0.5s ease;
	-moz-transition: all 0.5s ease;
	-ms-transition: all 0.5s ease;
	-o-transition: all 0.5s ease;
	transition: all 0.5s ease;
	
	text-decoration: none;
}

.subject_new {
	font-weight: bold;
}

.highlight {
		background: rgba(15,15,15,0.95);
border: 1px solid #232323;
text-shadow: 0px 1px 1px #171717;
  	color: #fff;
	padding-top: 3px;
	padding-bottom: 3px;
}

.pm_alert {
	background: #3f9889;
  	border: 1px solid #286d61;
	text-shadow: rgba(0,0,0,0.4) 0px 1px 1px;
	-moz-background-clip: padding;
	-webkit-background-clip: padding-box;
	background-clip: padding-box;
	-moz-border-radius: 2px;
	-webkit-border-radius: 2px;
	border-radius: 2px;
	text-align: center;
	padding: 6px 10px;
	color: #fff;
    font-family: 'Roboto Condensed', sans-serif;
    font-size: 13px;
	font-style: normal;
	font-weight: normal;
        -webkit-box-shadow: rgba(0,0,0,0.3) 0px 1px 4px, inset rgba(255,255,255,0.13) 0px 1px 0px;
      -moz-box-shadow: rgba(0,0,0,0.3) 0px 1px 4px, inset rgba(255,255,255,0.13) 0px 1px 0px;
      box-shadow: rgba(0,0,0,0.3) 0px 1px 4px, inset rgba(255,255,255,0.13) 0px 1px 0px;
}

.pm_alert a:link,
.pm_alert a:visited,
.pm_alert a:hover,
.pm_alert  a:active {
	color: #fff;
}

.red_alert {
	background: #646464;
    border: 1px solid #323131;
	text-shadow: rgba(0,0,0,0.4) 0px 1px 1px;
        -webkit-box-shadow: rgba(0,0,0,0.3) 0px 1px 4px, inset rgba(255,255,255,0.13) 0px 1px 0px;
      -moz-box-shadow: rgba(0,0,0,0.3) 0px 1px 4px, inset rgba(255,255,255,0.13) 0px 1px 0px;
      box-shadow: rgba(0,0,0,0.3) 0px 1px 4px, inset rgba(255,255,255,0.13) 0px 1px 0px;
	-moz-background-clip: padding;
	-webkit-background-clip: padding-box;
	background-clip: padding-box;
	text-align: center;
	padding: 6px 10px;
	-moz-border-radius: 2px;
	-webkit-border-radius: 2px;
	border-radius: 2px;	
	color: #fff;
    font-family: 'Roboto Condensed', sans-serif;
    font-size: 13px;
	font-style: normal;
	font-weight: normal;
}

.red_alert a:link,
.red_alert a:visited,
.red_alert a:hover,
.red_alert  a:active {
	color: #fff;
}

.high_warning {
	color: #ffffff;
}

.moderate_warning {
	color: #ffffff;
}

.low_warning {
	color: #ffffff;
}

.online {
	color: #15A018;
}

.offline {
	color: #C7C7C7;
}

div.error {
	padding: 5px 10px;
		background: rgba(15,15,15,0.95);
border-bottom: 2px solid #232323;
  border-top: 2px solid #232323;
text-shadow: 0px 1px 1px #171717;
  	color: #ccc;
	font-family: Source Sans Pro,Tahoma,Helvetica Neue,Arial,sans-serif;
	font-size: 14px;
	font-style: normal;
}

div.error p {
	margin: 0;
	color: #ccc;
	font-weight: normal;
}

div.error p em {
	font-style: normal;
	font-weight: bold;
	padding-left: 24px;
	display: block;
	color: #ccc;
	background: url(images/error.png) no-repeat 0;
}

div.error ul {
	margin-left: 24px;
}

.pagination {
	font-family: Source Sans Pro,Tahoma,Helvetica Neue,Arial,sans-serif;
	font-size: 13px;
	font-style: normal;
	padding-top: 10px;
	margin-bottom: 5px;
}

.tfoot .pagination,
.tcat .pagination {
	padding-top: 0;
}

.pagination .pages {
	color: #000;
}

.pagination .pagination_current,
.pagination a {
    background: rgba(15,15,15,0.95);
	color: #f1f1f1;
	text-shadow: rgba(0,0,0,0.4) 0px 1px 1px;
	-moz-box-shadow: rgba(0,0,0,0.15) 0px 1px 3px;
	-webkit-box-shadow: rgba(0,0,0,0.15) 0px 1px 3px;
	box-shadow: rgba(0,0,0,0.15) 0px 1px 3px;
	-moz-border-radius: 2px;
	-webkit-border-radius: 2px;
	border-radius: 2px;
	padding: 3px 6px;
}

.pagination a {
  	-moz-border-radius: 2px;
	-webkit-border-radius: 2px;
	border-radius: 2px;
}

.pagination .pagination_current {
  background: #3f9889;
  text-shadow: rgba(0,0,0,0.4) 0px 1px 1px;
  -moz-box-shadow: rgba(0,0,0,0.15) 0px 1px 3px;
  -webkit-box-shadow: rgba(0,0,0,0.15) 0px 1px 3px;
  box-shadow: rgba(0,0,0,0.15) 0px 1px 3px;
	color: #fff;
	padding: 3px 6px;
  	-moz-border-radius: 2px;
	-webkit-border-radius: 2px;
	border-radius: 2px;
}

.pagination a:hover {
	padding: 3px 6px;
	-moz-border-radius: 2px;
	-webkit-border-radius: 2px;
	border-radius: 2px;
	
	color: #fff;
	text-decoration: none;
}

.pagination .go_page img {
	margin-bottom: -4px;
}

.drop_go_page {
border-bottom: 2px solid #232323;
	padding: 4px;
}

.pagination_breadcrumb {
		background: rgba(15,15,15,0.95);
border: 2px solid #232323;
text-shadow: 0px 1px 1px #171717;
  	color: #ccc;
	outline: 1px solid #232323;
	padding: 5px;
	margin-top: 5px;
	font-weight: normal;
}

.pagination_breadcrumb_link {
	vertical-align: middle;
	cursor: pointer;
}

.thread_legend,
.thread_legend dd {
	margin: 0;
	padding: 0;
